#include <Servo.h>

const int SERVO_PIN = 9;
Servo  servo;
int angle = 0;
void setup() {
  servo.attach(SERVO_PIN);
}

void loop() {
  for(angle = 0; angle <= 270; angle += 0.1){
    servo.write(angle);
    delay(20);
  }

  for(angle = 270; angle >= 0; angle -=0.1){
    servo.write(angle);
    delay(20);
  }
}
